 async function login(e:FormEvent){e.preventDefault();if(!supabase)return setNotice('لم يكتمل إعداد الاتصال');setSaving(true);const {error}=await supabase.auth.signInWithPassword({email,password});setNotice(error?'تعذر تسجيل الدخول: تحققي من البريد وكلمة المرور':'');setSaving(false);}
 async function resendConfirmation(){if(!supabase)return;if(!email.trim())return setNotice('اكتبي البريد الإلكتروني أولًا ثم اضغطي إعادة إرسال رابط التفعيل.');setSaving(true);setNotice('');const {error}=await supabase.auth.resend({type:'signup',email:email.trim(),options:{emailRedirectTo:window.location.origin+import.meta.env.BASE_URL}});setNotice(error?'تعذر إرسال الرابط: '+authConnectionError(emailError(error.message)):'إذا كان البريد مسجّلًا وينتظر التأكيد، ستصلك رسالة جديدة. تحققي من البريد والرسائل غير المرغوبة.');setSaving(false);}
 async function signUp(e:FormEvent){e.preventDefault();if(!supabase)return;setNotice('');if(fullName.trim().length<3)return setNotice('يرجى كتابة الاسم الكامل');if(password.length<8)return setNotice('يجب ألا تقل كلمة المرور عن 8 أحرف');if(password!==confirmPassword)return setNotice('كلمتا المرور غير متطابقتين');setSaving(true);const {data,error}=await supabase.auth.signUp({email:email.trim(),password,options:{data:{full_name:fullName.trim()},emailRedirectTo:window.location.origin+import.meta.env.BASE_URL}});setSaving(false);if(error){setNotice('تعذر إنشاء الحساب: '+authConnectionError(emailError(error.message)));return;}setNotice(data.session?'تم إنشاء الحساب وتسجيل الدخول بنجاح':'تم إنشاء الحساب. تحققي من بريدك الإلكتروني واضغطي رابط تفعيل الحساب، ثم سجلي الدخول.');setRegister(false);setPassword('');setConfirmPassword('');}
 async function saveAttendance(e:FormEvent){e.preventDefault();if(!supabase||!staff)return;
 if(endTime<=startTime){setNotice('وقت النهاية يجب أن يكون بعد وقت البداية');return;}
 setSaving(true);setNotice('');
 const existing=sessions.find(s=>s.session_date===date&&s.study_type===studyType&&s.book_id===(bookId||null));
 if(existing&&!editingSessionId){setNotice('الجلسة موجودة مسبقًا. افتحيها من السجلات لتعديلها.');setSaving(false);return;}
 if(editingSessionId){const {error}=await supabase.from('sessions').update({session_date:date,study_type:studyType,book_id:bookId||null,description:sessionDescription.trim()||null,start_time:startTime,end_time:endTime}).eq('id',editingSessionId);setNotice(error?'تعذر تعديل الجلسة: '+error.message:'تم حفظ تعديلات الجلسة');if(!error){setEditingSessionId(null);setSessionDescription('');await reload();}setSaving(false);return;}
 const {data:session,error}=await supabase.from('sessions').insert({session_date:date,study_type:studyType,book_id:bookId||null,description:sessionDescription.trim()||null,start_time:startTime,end_time:endTime,created_by:uid}).select('id').single();
 if(error||!session){setNotice('تعذر إنشاء الجلسة: '+(error?.message||''));setSaving(false);return;}
 setNotice('تمت إضافة الجلسة إلى الجدول');setSessionDescription('');
 await reload();setSaving(false);
 }
 async function saveProfile(e:FormEvent){e.preventDefault();if(!supabase||!uid)return;const cleanName=displayName.trim();if(cleanName.length<3){setNotice('الاسم الكامل إلزامي ويجب ألا يقل عن 3 أحرف');return;}setSaving(true);const {error:profileError}=await supabase.from('profiles').update({full_name:cleanName}).eq('id',uid);if(profileError){setNotice('تعذر تغيير الاسم: '+profileError.message);setSaving(false);return;}const {error}=await supabase.auth.updateUser({data:{full_name:cleanName,bio:about.trim(),phone:contact.trim(),university:university.trim(),birth_date:birthDate||null,avatar_url:avatar}});setProfile(p=>p?{...p,full_name:cleanName}:p);setMembers(v=>v.map(m=>m.id===uid?{...m,full_name:cleanName}:m));setNotice(error?'تم تحديث الاسم، لكن تعذر حفظ بقية البيانات: '+error.message:'تم تحديث اسمك وبيانات ملفك الشخصي');setSaving(false);}
 async function uploadAvatar(file:File){if(!supabase||!uid)return;if(!file.type.startsWith('image/')){setNotice('اختاري صورة فقط');return;}setUploading(true);try{const img=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,480/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');if(!ctx)throw Error('تعذر معالجة الصورة');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let blob:Blob|null=null;for(const q of [0.75,0.6,0.45,0.3,0.2]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',q));if(blob&&blob.size<=50*1024)break;}if(!blob||blob.size>50*1024)throw Error('لم نتمكن من ضغط الصورة إلى 50 كيلوبايت');const path=uid+'/avatar.jpg';const {error}=await supabase.storage.from('nabt-avatars').upload(path,blob,{contentType:'image/jpeg',upsert:true});if(error)throw Error('تخزين الصور غير مهيأ بعد: '+error.message);const {data}=supabase.storage.from('nabt-avatars').getPublicUrl(path);const newUrl=data.publicUrl+'?v='+Date.now();const saved=await supabase.auth.updateUser({data:{avatar_url:newUrl}});if(saved.error)throw saved.error;setAvatar(newUrl);setNotice('تم ضغط الصورة ورفعها بنجاح ('+Math.ceil(blob.size/1024)+' كيلوبايت)');}catch(err){setNotice(err instanceof Error?err.message:'تعذر رفع الصورة');}finally{setUploading(false);}}
 function openSessionEdit(session:Session){setEditingSessionId(session.id);setDate(session.session_date);setStudyType(session.study_type);setBookId(session.book_id||'');setSessionDescription(session.description||'');setStartTime(session.start_time?.slice(0,5)||'09:00');setEndTime(session.end_time?.slice(0,5)||'11:00');const saved:Record<string,'present'|'absent'>={};for(const row of attendance.filter(a=>a.session_id===session.id))saved[row.member_id]=row.status;setSelected(saved);setView('admin');setAdminTab('sessions');window.location.hash='admin';setNotice('عدّلي بيانات الجلسة ثم احفظي التغييرات.');}
 function openBookEdit(book:Book){setEditingBookId(book.id);setBookTitle(book.title);setBookAuthor(book.author||'');setBookDescription(book.description||'');setBookLink(book.source_url||'');setBookStatus(book.status);setBookCover(null);setView('admin');setAdminTab('books');window.location.hash='admin';setNotice('يمكنك تعديل بيانات الكتاب وغلافه.');}
 function cancelBookEdit(){setEditingBookId(null);setBookTitle('');setBookAuthor('');setBookDescription('');setBookLink('');setBookCover(null);setBookStatus('planned');}
 async function confirmAction(){if(!confirmation||!supabase||saving)return;setSaving(true);const target=confirmation;try{if(target.kind==='logout'){const {error}=await supabase.auth.signOut();if(error)throw error;}else if(target.kind==='book'){const {error}=await supabase.from('books').delete().eq('id',target.id!);if(error)throw error;cancelBookEdit();await reload();setNotice('تم حذف الكتاب.');}else{const {error}=await supabase.from('sessions').delete().eq('id',target.id!);if(error)throw error;setEditingSessionId(null);await reload();setNotice('تم حذف الجلسة وسجلات حضورها.');}}catch(err){setNotice('تعذر تنفيذ العملية: '+(err instanceof Error?err.message:String(err)));}finally{setSaving(false);setConfirmation(null);}}
 async function addBook(e:FormEvent){e.preventDefault();if(!supabase||!director)return;
 if(!/^https:\/\/(drive\.google\.com|docs\.google\.com)\//i.test(bookLink.trim())){setNotice('أدخلي رابط ملف الكتاب من Google Drive');return;}
 setSaving(true);setNotice('');
 let coverUrl:string|null=editingBookId?(books.find(b=>b.id===editingBookId)?.cover_url||null):null;
 try{
 if(bookCover){
  if(!bookCover.type.startsWith('image/'))throw new Error('يجب اختيار صورة غلاف');
  const img=await createImageBitmap(bookCover);const canvas=document.createElement('canvas');
  const scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));
  const ctx=canvas.getContext('2d');if(!ctx)throw new Error('تعذر معالجة الغلاف');
  ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);img.close();
  const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/jpeg',0.8));
  if(!blob||blob.size>1048576)throw new Error('حجم الغلاف بعد المعالجة أكبر من 1 ميجابايت');
  const path=crypto.randomUUID()+'.jpg';
  const upload=await supabase.storage.from('nabt-book-covers').upload(path,blob,{contentType:'image/jpeg',upsert:false});
  if(upload.error)throw upload.error;
  coverUrl=supabase.storage.from('nabt-book-covers').getPublicUrl(path).data.publicUrl;
 }
 const payload={title:bookTitle.trim(),author:bookAuthor.trim()||null,description:bookDescription.trim()||null,cover_url:coverUrl,status:bookStatus,source_url:bookLink.trim()};
 const {error}=editingBookId?await supabase.from('books').update(payload).eq('id',editingBookId):await supabase.from('books').insert(payload);
 if(error)throw error;
 setNotice(editingBookId?'تم حفظ تعديلات الكتاب':'تمت إضافة الكتاب إلى المكتبة والرئيسية');cancelBookEdit();await reload();
 }catch(error){setNotice('تعذرت إضافة الكتاب: '+(error instanceof Error?error.message:String(error)));}
 finally{setSaving(false);}
 }
 async function changeUser(user:Profile,changes:{role?:Profile['role'];active?:boolean}){if(!supabase||!director||user.id===uid){setNotice('لا يمكن تعديل صلاحية أو حالة حسابك من هذه الصفحة.');return;}if(user.role==='director'&&changes.role&&changes.role!=='director'){setNotice('لا يمكن تخفيض صلاحية مديرة أخرى من هذه الواجهة.');return;}setSaving(true);const {error}=await supabase.from('profiles').update(changes).eq('id',user.id);setNotice(error?'تعذر تحديث المستخدم: '+error.message:'تم تحديث المستخدم بنجاح');if(!error)await reload();setSaving(false);}
